import{_ as r,o as e,c as l,a2 as t}from"./chunks/framework.CRFziyHp.js";const f=JSON.parse('{"title":"跑腿","description":"跑腿：灵萌 功能开启官方文档，面向站点管理员与运营人员，含配置步骤与注意事项。","frontmatter":{},"headers":[],"relativePath":"features/errand.md","filePath":"features/errand.md","lastUpdated":1785018026000}'),i={name:"features/errand.md"};function o(n,a,s,h,u,d){return e(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="跑腿" tabindex="-1">跑腿 <a class="header-anchor" href="#跑腿" aria-label="Permalink to &quot;跑腿&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>按区域配置帮取帮送类跑腿服务的范围、计价与开关，并处理跑腿订单。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>跑腿模块已在授权中开通。</li><li><a href="/features/map">高德地图</a> 已配置。</li><li><a href="/features/payment">支付与提现</a> 已配置。</li><li>外卖 / 本地生活相关菜单可见（跑腿入口在 <strong>商户管理 → 外卖</strong> 分组下）。</li></ul><h2 id="管理后台配置步骤" tabindex="-1">管理后台配置步骤 <a class="header-anchor" href="#管理后台配置步骤" aria-label="Permalink to &quot;管理后台配置步骤&quot;">​</a></h2><h3 id="_1-跑腿区域配置" tabindex="-1">1. 跑腿区域配置 <a class="header-anchor" href="#_1-跑腿区域配置" aria-label="Permalink to &quot;1. 跑腿区域配置&quot;">​</a></h3><p>路径：<strong>商户管理 → 外卖 → 跑腿区域配置</strong></p><p>为每个区域设置：</p><ul><li>是否启用跑腿</li><li>服务范围（距离 / 区域边界）</li><li>基础费用、里程费、时段加价等（以页面字段为准）</li><li>可选物品类型、重量上限</li></ul><p>保存后该区域用户端显示跑腿下单入口。</p><h3 id="_2-跑腿订单" tabindex="-1">2. 跑腿订单 <a class="header-anchor" href="#_2-跑腿订单" aria-label="Permalink to &quot;2. 跑腿订单&quot;">​</a></h3><p>路径：<strong>商户管理 → 外卖 → 跑腿订单</strong></p><ul><li>查看进行中 / 已完成订单</li><li>处理异常、取消、退款类工单（权限允许时）</li></ul><p>跑腿单派单通常与 <a href="/features/rider">骑手</a> 体系共用；策略细节在 <strong>区域外卖配置</strong> 与跑腿配置中分别维护。</p><h2 id="区域配置" tabindex="-1">区域配置 <a class="header-anchor" href="#区域配置" aria-label="Permalink to &quot;区域配置&quot;">​</a></h2><p>跑腿 <strong>仅区域级</strong> 生效：<strong>跑腿区域配置</strong> 每一行对应一个 region_id。</p><ul><li>与 <strong>区域外卖配置</strong> 相互独立：可只开跑腿不开外卖，或二者都开。</li><li>地图 Key 为全站共用；计价与范围按区域单独填。</li></ul><h2 id="验证是否生效" tabindex="-1">验证是否生效 <a class="header-anchor" href="#验证是否生效" aria-label="Permalink to &quot;验证是否生效&quot;">​</a></h2><ol><li>在 <strong>跑腿区域配置</strong> 开启测试区域并设置简单计价。</li><li>客户端填写取件 / 送达地址，能算出预估费用并成功下单支付。</li><li><strong>跑腿订单</strong> 列表出现新单；骑手接单后状态流转正常。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>没有跑腿入口</strong></p><ul><li>该区域 <strong>跑腿区域配置</strong> 未启用。</li><li>模块未授权；或 UI 未展示入口。</li></ul><p><strong>地址无法识别或费用为 0</strong></p><ul><li><a href="/features/map">高德地图</a> Key 或安全密钥错误。</li><li>起终点超出 <strong>服务范围</strong>。</li></ul><p><strong>无人接单</strong></p><ul><li>与外卖类似，需有在线 <a href="/features/rider">骑手</a>；检查派单策略。</li></ul><p><strong>与外卖订单混淆</strong></p><ul><li>外卖订单在 <strong>外卖订单</strong>；跑腿在 <strong>跑腿订单</strong>，业务类型不同。</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/features/takeaway">外卖</a></li><li><a href="/features/rider">骑手</a></li><li><a href="/features/map">地图与定位</a></li></ul>',31)])])}const g=r(i,[["render",o]]);export{f as __pageData,g as default};
